insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0984','economics','International','medium','classic','What is an exchange rate?','["The price of one currency in terms of another","The interest rate on savings","The tax on exports","The rate of inflation"]'::jsonb,'The price of one currency in terms of another','For example, an exchange rate tells how many rupees buy one US dollar.',10,2,array['international'],'en',true,'IMF Back to Basics and WTO glossary — https://www.imf.org/external/pubs/ft/fandd/basics/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0985','economics','Public finance','hard','classic','What is a public good?','["A good that people cannot easily be excluded from and that one person’s use does not reduce, like street lighting","Any good sold by a government shop","A luxury good","A good that is always free of charge"]'::jsonb,'A good that people cannot easily be excluded from and that one person’s use does not reduce, like street lighting','Public goods are non-excludable and non-rival, so markets tend to underprovide them.',10,2,array['public finance'],'en',true,'IMF Back to Basics and WTO glossary — https://www.imf.org/external/pubs/ft/fandd/basics/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0986','economics','Indicators','medium','classic','What is per capita income?','["The average income per person in a country or region","The total income of the richest person","The income tax rate","The wage of a government employee"]'::jsonb,'The average income per person in a country or region','Per capita income is total income divided by population.',10,2,array['indicators'],'en',true,'IMF Back to Basics and WTO glossary — https://www.imf.org/external/pubs/ft/fandd/basics/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict (id) do nothing;
