insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0992','music','Notation','medium','classic','Which symbol at the start of a staff shows which pitches the lines and spaces represent?','["Clef","Rest","Tie","Fermata"]'::jsonb,'Clef','Common clefs are the treble clef and the bass clef.',10,2,array['notation'],'en',true,'Open Music Theory — https://viva.pressbooks.pub/openmusictheory/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0993','music','Performance','medium','classic','What is singing a cappella?','["Singing without instrumental accompaniment","Singing very loudly","Singing in another language","Singing with an orchestra"]'::jsonb,'Singing without instrumental accompaniment','A cappella means in the style of the chapel in Italian.',10,2,array['performance'],'en',true,'Open Music Theory — https://viva.pressbooks.pub/openmusictheory/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0994','music','Composers','medium','classic','Who composed the piece known as the Moonlight Sonata?','["Ludwig van Beethoven","Wolfgang Amadeus Mozart","Johann Sebastian Bach","Frédéric Chopin"]'::jsonb,'Ludwig van Beethoven','Beethoven wrote the Piano Sonata No. 14, nicknamed the Moonlight Sonata, in 1801.',10,2,array['composers'],'en',true,'Open Music Theory — https://viva.pressbooks.pub/openmusictheory/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0995','music','Practice','easy','classic','What does a metronome do?','["Produces a steady beat to help keep tempo","Tunes guitar strings","Records music","Makes music louder"]'::jsonb,'Produces a steady beat to help keep tempo','Musicians set a metronome to a number of beats per minute.',10,2,array['practice'],'en',true,'Open Music Theory — https://viva.pressbooks.pub/openmusictheory/') on conflict (id) do nothing;
