insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1011','vocabulary','Spelling','medium','classic','Which spelling of the word meaning “to get or be given something” is correct?','["Receive","Recieve","Receeve","Riceive"]'::jsonb,'Receive','A common rule is i before e except after c, as in receive.',10,2,array['spelling'],'en',true,'Merriam-Webster Dictionary — https://www.merriam-webster.com/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1012','vocabulary','Context','medium','classic','In “They made a feasible plan,” what does “feasible” mean?','["Possible and practical","Expensive and slow","Secret and hidden","Funny and silly"]'::jsonb,'Possible and practical','A feasible plan can realistically be carried out.',10,2,array['context'],'en',true,'Merriam-Webster Dictionary — https://www.merriam-webster.com/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1013','vocabulary','Meaning','easy','classic','What does “humble” mean?','["Modest and not proud","Loud and boastful","Angry and rude","Rich and powerful"]'::jsonb,'Modest and not proud','A humble person does not think they are better than others.',10,2,array['meaning'],'en',true,'Merriam-Webster Dictionary — https://www.merriam-webster.com/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1014','vocabulary','Antonyms','medium','classic','Which word is the opposite of “optimistic”?','["Pessimistic","Hopeful","Cheerful","Positive"]'::jsonb,'Pessimistic','An optimist expects good outcomes; a pessimist expects bad ones.',10,2,array['antonyms'],'en',true,'Merriam-Webster Dictionary — https://www.merriam-webster.com/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1015','vocabulary','Meaning','hard','classic','What does “verbose” mean?','["Using more words than needed","Speaking very quietly","Using very few words","Speaking many languages"]'::jsonb,'Using more words than needed','A verbose explanation is wordy; a concise one is brief.',10,2,array['meaning'],'en',true,'Merriam-Webster Dictionary — https://www.merriam-webster.com/') on conflict (id) do nothing;
