insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1017','braille','Letters','medium','classic','Which dots represent the Braille letter Z?','["Dots 1, 3, 5, and 6","Dots 1, 3, 4, and 6","Dots 1, 3, 4, 5, and 6","Dots 1, 3, and 6"]'::jsonb,'Dots 1, 3, 5, and 6','Z adds dots 3 and 6 to the pattern for E, giving dots 1, 3, 5, and 6.',10,2,array['letters'],'en',true,'BANA, The ABCs of UEB — https://www.brailleauthority.org/ueb/abcs/abcs-ueb.html ; Government of India/NIEPVD, Standard Bharati Braille Codes — https://cdnbbsr.s3waas.gov.in/s36ee69d3769e832ec77c9584e0b7ba112/uploads/2025/01/20250104954295710.pdf') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1018','braille','Indicators','hard','classic','In Unified English Braille, which dots form the numeric indicator?','["Dots 3, 4, 5, and 6","Dot 6","Dots 5 and 6","Dots 2, 5, and 6"]'::jsonb,'Dots 3, 4, 5, and 6','The numeric indicator, dots 3, 4, 5, and 6, shows that the following letters a to j are digits.',10,2,array['indicators'],'en',true,'BANA, The ABCs of UEB — https://www.brailleauthority.org/ueb/abcs/abcs-ueb.html ; Government of India/NIEPVD, Standard Bharati Braille Codes — https://cdnbbsr.s3waas.gov.in/s36ee69d3769e832ec77c9584e0b7ba112/uploads/2025/01/20250104954295710.pdf') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1019','braille','Indicators','hard','classic','In Unified English Braille, which single dot is the capital letter indicator?','["Dot 6","Dot 1","Dot 3","Dot 4"]'::jsonb,'Dot 6','Dot 6 before a letter makes it a capital; two of them capitalize a whole word.',10,2,array['indicators'],'en',true,'BANA, The ABCs of UEB — https://www.brailleauthority.org/ueb/abcs/abcs-ueb.html ; Government of India/NIEPVD, Standard Bharati Braille Codes — https://cdnbbsr.s3waas.gov.in/s36ee69d3769e832ec77c9584e0b7ba112/uploads/2025/01/20250104954295710.pdf') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1020','braille','Numbers','medium','classic','After the numeric indicator, which letter’s pattern represents the digit 1?','["A","J","B","K"]'::jsonb,'A','The digits 1 to 9 use the patterns of letters a to i after the numeric indicator.',10,2,array['numbers'],'en',true,'BANA, The ABCs of UEB — https://www.brailleauthority.org/ueb/abcs/abcs-ueb.html ; Government of India/NIEPVD, Standard Bharati Braille Codes — https://cdnbbsr.s3waas.gov.in/s36ee69d3769e832ec77c9584e0b7ba112/uploads/2025/01/20250104954295710.pdf') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1021','braille','Numbers','hard','classic','After the numeric indicator, which letter’s pattern represents the digit 0?','["J","A","O","Z"]'::jsonb,'J','Zero uses the pattern of the letter j, dots 2, 4, and 5.',10,2,array['numbers'],'en',true,'BANA, The ABCs of UEB — https://www.brailleauthority.org/ueb/abcs/abcs-ueb.html ; Government of India/NIEPVD, Standard Bharati Braille Codes — https://cdnbbsr.s3waas.gov.in/s36ee69d3769e832ec77c9584e0b7ba112/uploads/2025/01/20250104954295710.pdf') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1022','braille','Punctuation','hard','classic','In Unified English Braille, which dots represent a full stop?','["Dots 2, 5, and 6","Dots 2 and 5","Dot 2","Dots 2, 3, and 6"]'::jsonb,'Dots 2, 5, and 6','The UEB full stop, or period, is dots 2, 5, and 6.',10,2,array['punctuation'],'en',true,'BANA, The ABCs of UEB — https://www.brailleauthority.org/ueb/abcs/abcs-ueb.html ; Government of India/NIEPVD, Standard Bharati Braille Codes — https://cdnbbsr.s3waas.gov.in/s36ee69d3769e832ec77c9584e0b7ba112/uploads/2025/01/20250104954295710.pdf') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1023','braille','Punctuation','hard','classic','In Unified English Braille, which single dot represents a comma?','["Dot 2","Dot 3","Dot 5","Dot 6"]'::jsonb,'Dot 2','The UEB comma is dot 2.',10,2,array['punctuation'],'en',true,'BANA, The ABCs of UEB — https://www.brailleauthority.org/ueb/abcs/abcs-ueb.html ; Government of India/NIEPVD, Standard Bharati Braille Codes — https://cdnbbsr.s3waas.gov.in/s36ee69d3769e832ec77c9584e0b7ba112/uploads/2025/01/20250104954295710.pdf') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1024','braille','History','easy','classic','Who invented the Braille reading and writing system?','["Louis Braille","Valentin Haüy","Helen Keller","Samuel Gridley Howe"]'::jsonb,'Louis Braille','Louis Braille, who was blind from childhood, published his system in 1829.',10,2,array['history'],'en',true,'BANA, The ABCs of UEB — https://www.brailleauthority.org/ueb/abcs/abcs-ueb.html ; Government of India/NIEPVD, Standard Bharati Braille Codes — https://cdnbbsr.s3waas.gov.in/s36ee69d3769e832ec77c9584e0b7ba112/uploads/2025/01/20250104954295710.pdf') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1025','braille','The cell','easy','classic','Which dots make up the left column of a Braille cell?','["Dots 1, 2, and 3","Dots 1 and 4","Dots 4, 5, and 6","Dots 2 and 5"]'::jsonb,'Dots 1, 2, and 3','Dots 1, 2, and 3 run down the left column; dots 4, 5, and 6 run down the right.',10,2,array['the cell'],'en',true,'BANA, The ABCs of UEB — https://www.brailleauthority.org/ueb/abcs/abcs-ueb.html ; Government of India/NIEPVD, Standard Bharati Braille Codes — https://cdnbbsr.s3waas.gov.in/s36ee69d3769e832ec77c9584e0b7ba112/uploads/2025/01/20250104954295710.pdf') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1026','braille','Numbers','medium','classic','After the numeric indicator, which letter’s pattern represents the digit 5?','["E","F","D","I"]'::jsonb,'E','The digit 5 uses the pattern of the letter e, dots 1 and 5.',10,2,array['numbers'],'en',true,'BANA, The ABCs of UEB — https://www.brailleauthority.org/ueb/abcs/abcs-ueb.html ; Government of India/NIEPVD, Standard Bharati Braille Codes — https://cdnbbsr.s3waas.gov.in/s36ee69d3769e832ec77c9584e0b7ba112/uploads/2025/01/20250104954295710.pdf') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1027','management','Strategy','easy','classic','What is a vision statement?','["A description of the future an organization hopes to achieve","A list of daily tasks","A record of last year’s sales","A job description for a manager"]'::jsonb,'A description of the future an organization hopes to achieve','A vision statement describes long-term aspirations; a mission statement describes present purpose.',10,2,array['strategy'],'en',true,'ISO 21502 project management guidance overview — https://www.iso.org/standard/74947.html ; UK Government Project Delivery Functional Standard — https://www.gov.uk/government/publications/project-delivery-functional-standard') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1028','management','Projects','hard','classic','What is the critical path in a project schedule?','["The longest chain of dependent tasks, which sets the shortest possible project duration","The most expensive task","The first task to begin","A list of optional tasks"]'::jsonb,'The longest chain of dependent tasks, which sets the shortest possible project duration','A delay to any task on the critical path delays the whole project.',10,2,array['projects'],'en',true,'ISO 21502 project management guidance overview — https://www.iso.org/standard/74947.html ; UK Government Project Delivery Functional Standard — https://www.gov.uk/government/publications/project-delivery-functional-standard') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1029','management','Projects','medium','classic','What is a work breakdown structure?','["A hierarchy that divides project work into smaller deliverables","A chart of employee salaries","A list of broken equipment","A schedule of staff holidays"]'::jsonb,'A hierarchy that divides project work into smaller deliverables','Breaking work into manageable parts helps with estimating and assigning tasks.',10,2,array['projects'],'en',true,'ISO 21502 project management guidance overview — https://www.iso.org/standard/74947.html ; UK Government Project Delivery Functional Standard — https://www.gov.uk/government/publications/project-delivery-functional-standard') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1030','management','People','medium','classic','In management, what does motivation refer to?','["The forces that drive people to work toward goals","The company’s legal structure","The cost of raw materials","The number of shifts in a day"]'::jsonb,'The forces that drive people to work toward goals','Recognition, purpose, growth, and fair pay can all affect motivation.',10,2,array['people'],'en',true,'ISO 21502 project management guidance overview — https://www.iso.org/standard/74947.html ; UK Government Project Delivery Functional Standard — https://www.gov.uk/government/publications/project-delivery-functional-standard') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1031','management','Organization','easy','classic','What does an organizational chart show?','["The structure and reporting relationships of an organization","The company’s monthly profit","The location of the office","The prices of products"]'::jsonb,'The structure and reporting relationships of an organization','Organizational charts show who reports to whom.',10,2,array['organization'],'en',true,'ISO 21502 project management guidance overview — https://www.iso.org/standard/74947.html ; UK Government Project Delivery Functional Standard — https://www.gov.uk/government/publications/project-delivery-functional-standard') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1032','management','Personal effectiveness','easy','classic','What is time management?','["Planning and controlling how time is spent on activities","Repairing clocks","Working without breaks","Measuring travel time"]'::jsonb,'Planning and controlling how time is spent on activities','Good time management helps people meet deadlines and reduce stress.',10,2,array['personal effectiveness'],'en',true,'ISO 21502 project management guidance overview — https://www.iso.org/standard/74947.html ; UK Government Project Delivery Functional Standard — https://www.gov.uk/government/publications/project-delivery-functional-standard') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1033','management','Change','medium','classic','What is change management?','["A structured approach to helping people and organizations move through change","Counting coins in a till","Replacing all managers every year","Changing office furniture"]'::jsonb,'A structured approach to helping people and organizations move through change','Change management includes communication, training, and support.',10,2,array['change'],'en',true,'ISO 21502 project management guidance overview — https://www.iso.org/standard/74947.html ; UK Government Project Delivery Functional Standard — https://www.gov.uk/government/publications/project-delivery-functional-standard') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1034','management','Risk','medium','classic','What is a contingency plan?','["A plan prepared in case a particular problem or emergency happens","The main daily work plan","A marketing slogan","A list of completed tasks"]'::jsonb,'A plan prepared in case a particular problem or emergency happens','Contingency plans help an organization respond quickly if risks occur.',10,2,array['risk'],'en',true,'ISO 21502 project management guidance overview — https://www.iso.org/standard/74947.html ; UK Government Project Delivery Functional Standard — https://www.gov.uk/government/publications/project-delivery-functional-standard') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1035','management','Organization','medium','classic','What is decentralization in an organization?','["Spreading decision-making authority to lower levels","Keeping all decisions with top managers","Closing branch offices","Merging departments into one"]'::jsonb,'Spreading decision-making authority to lower levels','Decentralization can speed up decisions close to customers.',10,2,array['organization'],'en',true,'ISO 21502 project management guidance overview — https://www.iso.org/standard/74947.html ; UK Government Project Delivery Functional Standard — https://www.gov.uk/government/publications/project-delivery-functional-standard') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1036','management','Agile','medium','classic','What is a retrospective in an agile team?','["A meeting to review what went well and what to improve","A meeting to hire new staff","A celebration of product launch only","A review of competitors’ prices"]'::jsonb,'A meeting to review what went well and what to improve','Retrospectives are held regularly so that teams keep improving how they work.',10,2,array['agile'],'en',true,'ISO 21502 project management guidance overview — https://www.iso.org/standard/74947.html ; UK Government Project Delivery Functional Standard — https://www.gov.uk/government/publications/project-delivery-functional-standard') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1037','business','Ownership','easy','classic','What is a partnership?','["A business owned by two or more people who share profits","A business owned by one person","A business owned by the government","A charity run by volunteers"]'::jsonb,'A business owned by two or more people who share profits','Partners share profits, decisions, and often liability according to their agreement.',10,2,array['ownership'],'en',true,'US Small Business Administration, Business Guide — https://www.sba.gov/business-guide') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1038','business','Ownership','medium','classic','What is a public limited company?','["A company whose shares can be bought and sold by the public","A company owned by the government","A business run by one owner","A partnership of two people"]'::jsonb,'A company whose shares can be bought and sold by the public','Public limited companies can list shares on a stock exchange.',10,2,array['ownership'],'en',true,'US Small Business Administration, Business Guide — https://www.sba.gov/business-guide') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1039','business','Marketing','easy','classic','What is a logo?','["A symbol or design that identifies a business","A business loan","A sales receipt","A type of contract"]'::jsonb,'A symbol or design that identifies a business','Logos help customers recognize a company quickly.',10,2,array['marketing'],'en',true,'US Small Business Administration, Business Guide — https://www.sba.gov/business-guide') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1040','business','Marketing','medium','classic','What is market research?','["Gathering information about customers, competitors, and markets","Buying goods at a market","Researching the history of money","Counting stock in a warehouse"]'::jsonb,'Gathering information about customers, competitors, and markets','Surveys, interviews, and sales data are common market research tools.',10,2,array['marketing'],'en',true,'US Small Business Administration, Business Guide — https://www.sba.gov/business-guide') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1041','business','Competition','easy','classic','What is a competitor?','["Another business offering similar products to the same customers","A business partner","A supplier of raw materials","A company employee"]'::jsonb,'Another business offering similar products to the same customers','Competitors compete for the same customers.',10,2,array['competition'],'en',true,'US Small Business Administration, Business Guide — https://www.sba.gov/business-guide') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1042','business','Finance','medium','classic','What is a dividend?','["A share of a company’s profits paid to shareholders","A loan from a bank","A tax on profits","An employee’s salary"]'::jsonb,'A share of a company’s profits paid to shareholders','Companies may pay dividends from profits, often quarterly or yearly.',10,2,array['finance'],'en',true,'US Small Business Administration, Business Guide — https://www.sba.gov/business-guide') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1043','business','Enterprise','easy','classic','What is a startup?','["A newly founded company that aims to grow quickly","A company that is closing down","A government department","A large old company"]'::jsonb,'A newly founded company that aims to grow quickly','Startups often develop new products or business models.',10,2,array['enterprise'],'en',true,'US Small Business Administration, Business Guide — https://www.sba.gov/business-guide') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1044','business','Marketing','medium','classic','What is a unique selling proposition?','["The feature that makes a product stand out from competitors","The lowest price in the market","A list of all products","A government licence"]'::jsonb,'The feature that makes a product stand out from competitors','A clear unique selling proposition tells customers why to choose this product.',10,2,array['marketing'],'en',true,'US Small Business Administration, Business Guide — https://www.sba.gov/business-guide') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1045','business','Finance','medium','classic','What is crowdfunding?','["Raising money from many people, usually online","Borrowing from one bank","Selling shares on a stock exchange only","Collecting taxes"]'::jsonb,'Raising money from many people, usually online','Crowdfunding platforms let many people contribute small amounts to a project.',10,2,array['finance'],'en',true,'US Small Business Administration, Business Guide — https://www.sba.gov/business-guide') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1046','business','Finance','medium','classic','What is an initial public offering?','["The first sale of a company’s shares to the public","The first product a company sells","A company’s first job advertisement","A business’s first loan"]'::jsonb,'The first sale of a company’s shares to the public','After an IPO, a company’s shares trade on a stock exchange.',10,2,array['finance'],'en',true,'US Small Business Administration, Business Guide — https://www.sba.gov/business-guide') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1047','accounting','Bookkeeping','medium','classic','In double-entry bookkeeping, which side of an account records a debit?','["The left side","The right side","The top of the page","A separate notebook"]'::jsonb,'The left side','Debits are recorded on the left side of an account and credits on the right.',10,2,array['bookkeeping'],'en',true,'IFRS Foundation, issued standards — https://www.ifrs.org/issued-standards/list-of-standards/ ; IAASB standards — https://www.iaasb.org/publications') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1048','accounting','Bookkeeping','medium','classic','In double-entry bookkeeping, which side of an account records a credit?','["The right side","The left side","The bottom of the page","The cover page"]'::jsonb,'The right side','Credits are recorded on the right side of an account.',10,2,array['bookkeeping'],'en',true,'IFRS Foundation, issued standards — https://www.ifrs.org/issued-standards/list-of-standards/ ; IAASB standards — https://www.iaasb.org/publications') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1049','accounting','Receivables','medium','classic','What is a bad debt?','["An amount owed to the business that is not expected to be collected","A loan with low interest","A debt paid early","A tax refund"]'::jsonb,'An amount owed to the business that is not expected to be collected','Bad debts are written off as an expense.',10,2,array['receivables'],'en',true,'IFRS Foundation, issued standards — https://www.ifrs.org/issued-standards/list-of-standards/ ; IAASB standards — https://www.iaasb.org/publications') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1050','accounting','Reporting','easy','classic','What is a financial year?','["A twelve-month period used for accounting and reporting","Any calendar month","The age of a company","A ten-year business plan"]'::jsonb,'A twelve-month period used for accounting and reporting','India’s financial year runs from 1 April to 31 March.',10,2,array['reporting'],'en',true,'IFRS Foundation, issued standards — https://www.ifrs.org/issued-standards/list-of-standards/ ; IAASB standards — https://www.iaasb.org/publications') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1051','accounting','Cash','medium','classic','What is a bank reconciliation?','["Comparing the cash book with the bank statement and explaining differences","Opening a new bank account","Taking a loan from a bank","Changing banks"]'::jsonb,'Comparing the cash book with the bank statement and explaining differences','Reconciliation finds items such as uncleared cheques and bank charges.',10,2,array['cash'],'en',true,'IFRS Foundation, issued standards — https://www.ifrs.org/issued-standards/list-of-standards/ ; IAASB standards — https://www.iaasb.org/publications') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1052','accounting','Accruals','hard','classic','What is an accrued expense?','["An expense that has been incurred but not yet paid","An expense paid in advance","Income received early","A fixed asset"]'::jsonb,'An expense that has been incurred but not yet paid','Unpaid wages at the end of a period are an example of accrued expenses.',10,2,array['accruals'],'en',true,'IFRS Foundation, issued standards — https://www.ifrs.org/issued-standards/list-of-standards/ ; IAASB standards — https://www.iaasb.org/publications') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1053','accounting','Accruals','hard','classic','What is a prepaid expense?','["A payment made in advance for future benefits, recorded as an asset","An unpaid bill","Revenue from sales","A long-term loan"]'::jsonb,'A payment made in advance for future benefits, recorded as an asset','Insurance paid for the coming year is a prepaid expense.',10,2,array['accruals'],'en',true,'IFRS Foundation, issued standards — https://www.ifrs.org/issued-standards/list-of-standards/ ; IAASB standards — https://www.iaasb.org/publications') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1054','accounting','Inventory','medium','classic','Under the FIFO inventory method, which costs are assigned to goods sold first?','["The oldest costs","The newest costs","The average of all costs","The highest costs"]'::jsonb,'The oldest costs','FIFO stands for first in, first out.',10,2,array['inventory'],'en',true,'IFRS Foundation, issued standards — https://www.ifrs.org/issued-standards/list-of-standards/ ; IAASB standards — https://www.iaasb.org/publications') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1055','accounting','Assets','medium','classic','What is a current asset?','["An asset expected to be turned into cash or used up within a year","A building owned for many years","A long-term loan","The owner’s capital"]'::jsonb,'An asset expected to be turned into cash or used up within a year','Cash, receivables, and inventory are current assets.',10,2,array['assets'],'en',true,'IFRS Foundation, issued standards — https://www.ifrs.org/issued-standards/list-of-standards/ ; IAASB standards — https://www.iaasb.org/publications') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1056','accounting','Capital','easy','classic','In a sole trader’s accounts, what is capital?','["Money or other assets the owner invests in the business","Money the business owes suppliers","The business’s sales for a year","A bank overdraft"]'::jsonb,'Money or other assets the owner invests in the business','Capital is part of the owner’s equity.',10,2,array['capital'],'en',true,'IFRS Foundation, issued standards — https://www.ifrs.org/issued-standards/list-of-standards/ ; IAASB standards — https://www.iaasb.org/publications') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1057','commerce','Payments','medium','classic','What is a cash discount?','["A reduction offered for paying promptly","A discount for buying in bulk only","Extra charge for paying in cash","A free gift with a purchase"]'::jsonb,'A reduction offered for paying promptly','A cash discount encourages buyers to pay early.',10,2,array['payments'],'en',true,'International Trade Centre SME Trade Academy and WTO glossary — https://learning.intracen.org/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1058','commerce','Logistics','medium','classic','What is a supply chain?','["The network of organizations and activities that moves a product from raw materials to the customer","A chain used to lock warehouses","A list of company shareholders","A group of retail shops only"]'::jsonb,'The network of organizations and activities that moves a product from raw materials to the customer','Supply chains include suppliers, manufacturers, distributors, and retailers.',10,2,array['logistics'],'en',true,'International Trade Centre SME Trade Academy and WTO glossary — https://learning.intracen.org/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1059','commerce','Trade','hard','classic','What is a consignment in trade?','["Goods sent to an agent who sells them on the owner’s behalf","Goods bought on credit","A customer’s complaint","A government trade ban"]'::jsonb,'Goods sent to an agent who sells them on the owner’s behalf','The consignor keeps ownership until the consignee sells the goods.',10,2,array['trade'],'en',true,'International Trade Centre SME Trade Academy and WTO glossary — https://learning.intracen.org/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1060','commerce','Documents','medium','classic','What is a credit note?','["A document from a seller that reduces the amount a buyer owes, for example after a return","A bank loan agreement","A receipt for cash","A purchase order"]'::jsonb,'A document from a seller that reduces the amount a buyer owes, for example after a return','Credit notes are issued for returns, overcharges, or allowances.',10,2,array['documents'],'en',true,'International Trade Centre SME Trade Academy and WTO glossary — https://learning.intracen.org/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1061','commerce','Documents','medium','classic','What is a debit note?','["A document a buyer sends to a seller asking for the amount owed to be reduced","A seller’s price list","A bank statement","A delivery receipt"]'::jsonb,'A document a buyer sends to a seller asking for the amount owed to be reduced','Buyers issue debit notes, for example when they return faulty goods.',10,2,array['documents'],'en',true,'International Trade Centre SME Trade Academy and WTO glossary — https://learning.intracen.org/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1062','commerce','Retail','easy','classic','What is a chain store?','["One of many shops with the same owner and brand","A shop that sells chains","A single independent shop","A wholesale market"]'::jsonb,'One of many shops with the same owner and brand','Chain stores share branding, products, and central management.',10,2,array['retail'],'en',true,'International Trade Centre SME Trade Academy and WTO glossary — https://learning.intracen.org/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1063','commerce','Retail','easy','classic','What is a barcode used for in a shop?','["Identifying products quickly at checkout and in stock control","Decorating the packaging","Showing the product’s weight only","Locking the product"]'::jsonb,'Identifying products quickly at checkout and in stock control','Scanning a barcode looks up the product’s details and price.',10,2,array['retail'],'en',true,'International Trade Centre SME Trade Academy and WTO glossary — https://learning.intracen.org/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1064','commerce','Insurance','easy','classic','What is insurance?','["An arrangement in which a company pays for specified losses in return for premiums","A type of bank savings account","A tax on goods","A discount on purchases"]'::jsonb,'An arrangement in which a company pays for specified losses in return for premiums','Insurance spreads the cost of losses across many policyholders.',10,2,array['insurance'],'en',true,'International Trade Centre SME Trade Academy and WTO glossary — https://learning.intracen.org/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1065','commerce','International trade','medium','classic','What is a free trade agreement?','["An agreement between countries to reduce trade barriers such as tariffs","A rule that all goods must be free","A ban on all imports","A contract between two shops"]'::jsonb,'An agreement between countries to reduce trade barriers such as tariffs','Free trade agreements make it easier and cheaper to trade between member countries.',10,2,array['international trade'],'en',true,'International Trade Centre SME Trade Academy and WTO glossary — https://learning.intracen.org/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1066','commerce','Payments','easy','classic','What is a digital wallet?','["An app that stores payment details so you can pay electronically","A leather wallet with a chip","A bank branch","A type of cash register"]'::jsonb,'An app that stores payment details so you can pay electronically','Digital wallets let people pay by phone without cash or cards.',10,2,array['payments'],'en',true,'International Trade Centre SME Trade Academy and WTO glossary — https://learning.intracen.org/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict (id) do nothing;
